import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FileService } from 'src/app/core/services/file.service';
import { OrderByDatePipe } from 'src/app/core/order-by-date.pipe';

@Component({
  selector: 'app-student-files',
  standalone: true,
  imports: [CommonModule, OrderByDatePipe],
  templateUrl: './student-files.component.html',
  styleUrls: ['./student-files.component.scss']
})
export class StudentFilesComponent implements OnInit {
  classId!: number;
  files: any[] = [];
  filteredFiles: any[] = [];
  loading = true;

  selectedType = 'Tous';
  resourceTypes = [
    { label: 'Tous', icon: '🌍' },
    { label: 'Cours', icon: '📘' },
    { label: 'TD', icon: '🧩' },
    { label: 'TP', icon: '🧪' },
    { label: 'Autre', icon: '📄' }
  ];

  currentPage = 1;
  itemsPerPage = 10;

  constructor(private route: ActivatedRoute, private fileService: FileService) {}

  ngOnInit() {
    this.classId = +this.route.snapshot.params['id'];
    this.fileService.getFilesByClass(this.classId).subscribe({
      next: res => {
        this.files = res || [];
        this.files.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

        this.updateFilteredFiles();
        this.loading = false;
      },
      error: err => {
        console.error('Erreur chargement fichiers:', err);
        this.loading = false;
      }
    });
  }

  setSelectedType(type: string) {
    this.selectedType = type;
    this.currentPage = 1;
    this.updateFilteredFiles();
  }

  updateFilteredFiles() {
    let filtered =
      this.selectedType === 'Tous'
        ? [...this.files]
        : this.files.filter(f => this.getTypeLabel(f.type) === this.selectedType);

    const start = (this.currentPage - 1) * this.itemsPerPage;
    this.filteredFiles = filtered.slice(start, start + this.itemsPerPage);
  }

  getCount(type: string): number {
    if (type === 'Tous') return this.files.length;
    return this.files.filter(f => this.getTypeLabel(f.type) === type).length;
  }

  getTypeLabel(type: any): string {
    if (typeof type === 'number') {
      switch (type) {
        case 0: return 'Cours';
        case 1: return 'TD';
        case 2: return 'TP';
        case 3: return 'Autre';
      }
    }
    if (typeof type === 'string') {
      switch (type.toLowerCase()) {
        case 'cours': return 'Cours';
        case 'td': return 'TD';
        case 'tp': return 'TP';
        case 'autre': return 'Autre';
      }
    }
    return 'Autre';
  }

  // 🔹 Découpe titre et description si "—" existe
  getTitleOnly(fullTitle: string): string {
    return fullTitle.includes('—') ? fullTitle.split('—')[0].trim() : fullTitle;
  }

  getDescriptionOnly(fullTitle: string): string {
    return fullTitle.includes('—') ? fullTitle.split('—')[1].trim() : '';
  }

  get totalPages(): number {
    const count =
      this.selectedType === 'Tous'
        ? this.files.length
        : this.files.filter(f => this.getTypeLabel(f.type) === this.selectedType).length;
    return Math.ceil(count / this.itemsPerPage);
  }
downloadFile(file: any) {
  // 💡 Force le téléchargement avec Angular
  const url = file.fileUrl;

  fetch(url)
    .then(response => response.blob())
    .then(blob => {
      // Crée un lien temporaire invisible
      const blobUrl = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = blobUrl;
      a.download = file.title || 'fichier';
      document.body.appendChild(a);
      a.click();

      // Nettoyage
      a.remove();
      window.URL.revokeObjectURL(blobUrl);
    })
    .catch(err => {
      console.error('Erreur téléchargement :', err);
      alert('❌ Impossible de télécharger le fichier pour le moment.');
    });
}

  changePage(page: number) {
    if (page >= 1 && page <= this.totalPages) {
      this.currentPage = page;
      this.updateFilteredFiles();
    }
  }
}
<section class="container py-5">
  <h2 class="fw-bold text-center mb-4">📚 Ressources de la classe</h2>

  <!-- 🔹 Barre de filtres -->
  <div class="filter-bar text-center mb-4">
    <button
      *ngFor="let type of resourceTypes"
      class="btn mx-1 mb-2"
      [ngClass]="{
        'btn-dark': selectedType === 'Tous' && type.label === 'Tous',
        'btn-outline-dark': selectedType !== 'Tous' && type.label === 'Tous',
        'btn-primary': selectedType === type.label && type.label === 'Cours',
        'btn-success': selectedType === type.label && type.label === 'TD',
        'btn-warning': selectedType === type.label && type.label === 'TP',
        'btn-danger': selectedType === type.label && type.label === 'Autre',
        'btn-outline-primary': selectedType !== type.label && type.label === 'Cours',
        'btn-outline-success': selectedType !== type.label && type.label === 'TD',
        'btn-outline-warning': selectedType !== type.label && type.label === 'TP',
        'btn-outline-danger': selectedType !== type.label && type.label === 'Autre'
      }"
      (click)="setSelectedType(type.label)"
    >
      {{ type.icon }} {{ type.label }}
      <span class="badge bg-light text-dark ms-1">{{ getCount(type.label) }}</span>
    </button>
  </div>

  <div *ngIf="loading" class="text-center my-5">
    <div class="spinner-border text-primary"></div>
    <p class="text-muted mt-2">Chargement des ressources...</p>
  </div>

  <!-- 📁 Liste -->
  <div *ngIf="!loading && filteredFiles.length > 0; else noFiles">
    <div class="files-grid">
      <div class="file-card shadow-sm" *ngFor="let f of filteredFiles | orderByDate">
        <div class="file-type" [ngClass]="getTypeLabel(f.type).toLowerCase()">
          {{ getTypeLabel(f.type) }}
        </div>

        <!-- ✅ Affichage titre + description séparée -->
        <h5 class="file-title">{{ getTitleOnly(f.title) }}</h5>
        <p *ngIf="getDescriptionOnly(f.title)" class="file-description text-muted small">
          {{ getDescriptionOnly(f.title) }}
        </p>

        <p class="file-date text-muted small mb-2">
          <i class="bi bi-calendar-event me-1"></i>
          Ajouté le {{ f.createdAt | date: 'dd MMM yyyy, HH:mm' }}
        </p>

        <div class="file-actions">
          <a [href]="f.fileUrl" target="_blank" class="btn btn-outline-primary btn-sm w-100">
            <i class="bi bi-download me-1"></i> Télécharger
          </a>
        </div>
      </div>
    </div>

    <!-- 📄 Pagination -->
    <nav *ngIf="totalPages > 1" class="mt-4">
      <ul class="pagination justify-content-center">
        <li class="page-item" [class.disabled]="currentPage === 1">
          <button class="page-link" (click)="changePage(currentPage - 1)">Précédent</button>
        </li>

        <li
          class="page-item"
          *ngFor="let page of [].constructor(totalPages); let i = index"
          [class.active]="currentPage === i + 1"
        >
          <button class="page-link" (click)="changePage(i + 1)">
            {{ i + 1 }}
          </button>
        </li>

        <li class="page-item" [class.disabled]="currentPage === totalPages">
          <button class="page-link" (click)="changePage(currentPage + 1)">Suivant</button>
        </li>
      </ul>
    </nav>
  </div>

  <ng-template #noFiles>
    <div class="alert alert-info text-center mt-5">
      📭 Aucune ressource disponible pour cette classe.
    </div>
  </ng-template>
</section>
